#include <algorithm>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <queue>
#include <string>
#include <vector>
using namespace std;class LibraryItem{protected:int id;string title,publisher,category,location;int year,total,available;public:LibraryItem(int i,string t,string p,int y,string c,string l,int copies):id(i),title(move(t)),publisher(move(p)),category(move(c)),location(move(l)),year(y),total(copies),available(copies){}virtual~LibraryItem()=default;int getId()const{return id;}const string&getTitle()const{return title;}const string&getCategory()const{return category;}bool borrow(){if(available<=0)return false;--available;return true;}void giveBack(){if(available<total)++available;}virtual string type()const=0;virtual string extra()const=0;virtual double lateFee(int d)const{return d>0?d*2:0;}void show()const{cout<<id<<" | "<<type()<<" | "<<title<<" | "<<publisher<<" | "<<year<<" | "<<category<<" | "<<available<<'/'<<total<<" | "<<extra()<<'\n';}};class Book:public LibraryItem{string author,isbn;public:Book(int i,string t,string a,string x,int y,int c):LibraryItem(i,move(t),"General",y,"Book","Shelf",c),author(move(a)),isbn(move(x)){}string type()const override{return"Book";}string extra()const override{return author+" ISBN="+isbn;}};class EBook:public LibraryItem{string format;public:EBook(int i,string t,string f,int y):LibraryItem(i,move(t),"Digital",y,"EBook","Online",999),format(move(f)){}string type()const override{return"EBook";}string extra()const override{return format;}double lateFee(int)const override{return 0;}};class DVD:public LibraryItem{int duration;public:DVD(int i,string t,int d,int y,int c):LibraryItem(i,move(t),"Media",y,"DVD","Media",c),duration(d){}string type()const override{return"DVD";}string extra()const override{return to_string(duration)+" min";}double lateFee(int d)const override{return d>0?d*5:0;}};class Journal:public LibraryItem{string issue;public:Journal(int i,string t,string is,int y,int c):LibraryItem(i,move(t),"Academic",y,"Journal","Periodicals",c),issue(move(is)){}string type()const override{return"Journal";}string extra()const override{return issue;}};class User{protected:int id;string name;public:User(int i,string n):id(i),name(move(n)){}virtual~User()=default;int getId()const{return id;}virtual int maxBorrow()const=0;};class Member:public User{public:using User::User;int maxBorrow()const override{return 5;}};class Librarian:public User{public:using User::User;int maxBorrow()const override{return 20;}};class Guest:public User{public:using User::User;int maxBorrow()const override{return 0;}};struct BorrowRecord{int userId,itemId;string status;};class LibrarySystem{vector<shared_ptr<LibraryItem>>items;vector<shared_ptr<User>>users;vector<BorrowRecord>records;map<int,queue<int>>reservations;shared_ptr<LibraryItem>item(int id){for(auto&i:items)if(i->getId()==id)return i;return{};}shared_ptr<User>user(int id){for(auto&u:users)if(u->getId()==id)return u;return{};}int active(int uid)const{int n=0;for(auto&r:records)if(r.userId==uid&&r.status=="Borrowed")++n;return n;}public:LibrarySystem(){items.push_back(make_shared<Book>(1,"Clean Code","Robert Martin","9780132350884",2008,3));items.push_back(make_shared<EBook>(2,"Modern C++","PDF",2024));items.push_back(make_shared<DVD>(3,"Algorithms Lecture",90,2025,2));items.push_back(make_shared<Journal>(4,"AI Review","Vol.12",2026,2));users.push_back(make_shared<Member>(1,"Member"));users.push_back(make_shared<Librarian>(2,"Librarian"));users.push_back(make_shared<Guest>(3,"Guest"));}void list()const{for(auto&i:items)i->show();}void search(){string q;cin>>ws;getline(cin,q);for(auto&i:items)if(i->getTitle().find(q)!=string::npos||i->getCategory().find(q)!=string::npos)i->show();}void borrow(){int uid,iid;cin>>uid>>iid;auto u=user(uid);auto i=item(iid);if(!u||!i||active(uid)>=u->maxBorrow())return;if(!i->borrow()){reservations[iid].push(uid);cout<<"Reserved\n";return;}records.push_back({uid,iid,"Borrowed"});}void ret(){int uid,iid,late;cin>>uid>>iid>>late;for(auto&r:records)if(r.userId==uid&&r.itemId==iid&&r.status=="Borrowed"){r.status="Returned";auto i=item(iid);if(i){i->giveBack();cout<<"Late fee "<<i->lateFee(late)<<'\n';}if(!reservations[iid].empty()){cout<<"Reservation available for user "<<reservations[iid].front()<<'\n';reservations[iid].pop();}return;}}void report()const{map<int,int>count;for(auto&r:records)count[r.itemId]++;for(auto&x:count)cout<<"Item "<<x.first<<" borrowed "<<x.second<<" times\n";}void save()const{ofstream o("borrow_records.txt");for(auto&r:records)o<<r.userId<<'|'<<r.itemId<<'|'<<r.status<<'\n';}void run(){for(;;){cout<<"\nAdvanced Library\n1 List 2 Search 3 Borrow/reserve 4 Return/fine 5 Reports 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)list();else if(c==2)search();else if(c==3)borrow();else if(c==4)ret();else if(c==5)report();}}};int main(){LibrarySystem{}.run();}
